"use client";

import * as React from "react";
import { Dialog as SheetPrimitive } from "radix-ui";
import { Cross2Icon } from "@radix-ui/react-icons"

import { cn } from "@/utils/class-names";
import Button from "@/components/ui/Button";

function Sheet({ ...props }: React.ComponentProps<typeof SheetPrimitive.Root>) {
  return <SheetPrimitive.Root data-slot="sheet" {...props} />;
}

function SheetTrigger({
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Trigger>) {
  return <SheetPrimitive.Trigger data-slot="sheet-trigger" {...props} />;
}

function SheetClose({
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Close>) {
  return <SheetPrimitive.Close data-slot="sheet-close" {...props} />;
}

function SheetPortal({
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Portal>) {
  return <SheetPrimitive.Portal data-slot="sheet-portal" {...props} />;
}

function SheetOverlay({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Overlay>) {
  return (
    <SheetPrimitive.Overlay
      data-slot="sheet-overlay"
      className={cn(
        "fixed inset-0 bg-gray-9a backdrop-blur-xs z-50 data-[state=open]:animate-sheet-overlay-show",
        className
      )}
      {...props}
    />
  );
}

function SheetContent({
  className,
  children,
  side = "right",
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Content> & {
  side?: "top" | "right" | "bottom" | "left";
}) {
  return (
    <SheetPortal>
      <SheetOverlay />
      <SheetPrimitive.Content
        data-slot="sheet-content"
        className={cn(
          "bg-gray-1 fixed z-50 flex flex-col gap-1 shadow-lg",
          side === "right" &&
            "data-[state=open]:animate-sheet-right-open data-[state=closed]:animate-sheet-right-closed inset-y-0 right-0 h-full w-3/4 border-l sm:max-w-sm border-gray-a6",
          side === "left" &&
            "data-[state=open]:animate-sheet-left-open data-[state=closed]:animate-sheet-left-closed inset-y-0 left-0 h-full w-3/4 border-r sm:max-w-sm border-gray-a6",
          side === "top" &&
            "data-[state=open]:animate-sheet-top-open data-[state=closed]:animate-sheet-top-closed inset-x-0 top-0 h-auto border-b border-gray-a6",
          side === "bottom" &&
            "data-[state=open]:animate-sheet-bottom-open data-[state=closed]:animate-sheet-bottom-closed inset-x-0 bottom-0 h-auto border-t border-gray-a6",
          className
        )}
        {...props}
      >
        {children}
        <SheetPrimitive.Close className=" absolute top-0.5 right-0.5" asChild>
          <Button mode="link">
          <Cross2Icon className="icon" />
          <span className="sr-only">Close</span>
          </Button>
        </SheetPrimitive.Close>
      </SheetPrimitive.Content>
    </SheetPortal>
  );
}

function SheetHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-header"
      className={cn("flex flex-col gap-1.5 p-2", className)}
      {...props}
    />
  );
}

function SheetFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-footer"
      className={cn("mt-auto flex flex-col gap-1 p-2", className)}
      {...props}
    />
  );
}

function SheetTitle({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Title>) {
  return (
    <SheetPrimitive.Title
      data-slot="sheet-title"
      className={cn("text-gray-12 font-semibold", className)}
      {...props}
    />
  );
}

function SheetDescription({
  className,
  ...props
}: React.ComponentProps<typeof SheetPrimitive.Description>) {
  return (
    <SheetPrimitive.Description
      data-slot="sheet-description"
      className={cn("text-gray-11 text-sm", className)}
      {...props}
    />
  );
}

export {
  Sheet,
  SheetTrigger,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetFooter,
  SheetTitle,
  SheetDescription,
};

@theme animatons {
  --animate-sheet-overlay-show: sheetOverlayShow 150ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-sheet-right-open: sheetRightOpen 250ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-sheet-right-closed: sheetRightClosed 200ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-sheet-left-open: sheetLeftOpen 250ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-sheet-left-closed: sheetLeftClosed 200ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-sheet-top-open: sheetTopOpen 250ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-sheet-top-closed: sheetTopClosed 200ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-sheet-bottom-open: sheetBottomOpen 250ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-sheet-bottom-closed: sheetBottomClosed 200ms cubic-bezier(0.16, 1, 0.3, 1);
}

@layer components {
  @keyframes sheetOverlayShow {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes sheetRightOpen {
    from {
      transform: translate3d(100%, 0, 0);
    }
    to {
      transform: translate3d(0, 0, 0);
    }
  }

  @keyframes sheetRightClosed {
    from {
      transform: translate3d(0, 0, 0);
    }
    to {
      transform: translate3d(100%, 0, 0);
    }
  }

  @keyframes sheetLeftOpen {
    from {
      transform: translate3d(-100%, 0, 0);
    }
    to {
      transform: translate3d(0, 0, 0);
    }
  }

  @keyframes sheetLeftClosed {
    from {
      transform: translate3d(0, 0, 0);
    }
    to {
      transform: translate3d(-100%, 0, 0);
    }
  }

  @keyframes sheetTopOpen {
    from {
      transform: translate3d(0, -100%, 0);
    }
    to {
      transform: translate3d(0, 0, 0);
    }
  }

  @keyframes sheetTopClosed {
    from {
      transform: translate3d(0, 0, 0);
    }
    to {
      transform: translate3d(0, -100%, 0);
    }
  }

  @keyframes sheetBottomOpen {
    from {
      transform: translate3d(0, 100%, 0);
    }
    to {
      transform: translate3d(0, 0, 0);
    }
  }

  @keyframes sheetBottomClosed {
    from {
      transform: translate3d(0, 0, 0);
    }
    to {
      transform: translate3d(0, 100%, 0);
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  @layer components {
    [data-slot="sheet-overlay"],
    [data-slot="sheet-content"] {
      animation: none;
    }
  }
}
